import itertools
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 4))
    pairs = []
    for _ in range(n):
        a = draw(st.integers(-4, 4))
        b = draw(st.integers(-4, 4))
        l, r = min(a, b), max(a, b)
        pairs.append((l, r))
    lines = [str(n)] + [f"{l} {r}" for l, r in pairs]
    return "\n".join(lines) + "\n"

def _parse(inp):
    t = inp.split()
    n = int(t[0])
    pairs = [(int(t[1 + 2 * i]), int(t[2 + 2 * i])) for i in range(n)]
    return n, pairs

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 1:
            return False
        n = int(t[0])
        if not (1 <= n <= 2 * 10**5):
            return False
        if len(t) != 1 + 2 * n:
            return False
        vals = [int(x) for x in t[1:]]
        for i in range(n):
            l, r = vals[2 * i], vals[2 * i + 1]
            if not (-10**9 <= l <= r <= 10**9):
                return False
        return True
    except Exception:
        return False

def ref(inp):
    n, pairs = _parse(inp)
    for combo in itertools.product(*[range(l, r + 1) for l, r in pairs]):
        if sum(combo) == 0:
            return "Yes\n" + " ".join(map(str, combo))
    return "No"

def same(inp, expected, got):
    n, pairs = _parse(inp)
    exp_tokens = expected.split()
    got_tokens = got.split()
    if not exp_tokens:
        return False
    if exp_tokens[0] == "No":
        return got_tokens == ["No"]
    if not got_tokens or got_tokens[0] != "Yes":
        return False
    try:
        vals = [int(x) for x in got_tokens[1:]]
    except Exception:
        return False
    if len(vals) != n:
        return False
    for v, (l, r) in zip(vals, pairs):
        if not (l <= v <= r):
            return False
    return sum(vals) == 0
